-- Phong Than 2026-10-04 (agent lbdaosi): Lenh Bai Dao Si / Lenh Bai Di Nhan, servertimer side.
-- No main() here: dofile'd into the servertimer state by script\phongthan\ext\lbdaosi.lua (minute tick, needs
-- "lbdaosi" in PTADM_EXT_NAMES) and by the web admin bridge commands. Generated by scratchpad\lbdaosi\gen.py.
--  * every minute: tasks 2613 / 2614 are sent again to every online player (KPlayer::SyncCurPlayer clears the
--    client copy at each world entry);
--  * admin sets for offline characters wait in admin_bridge\lbdaosi_pending.txt and are applied at login;
--  * Dao Si / Di Nhan characters get their token once (tasks 2615 / 2616 = 1 when given or already owned).

PTLB_T_DS = 2613      -- Dao Si set: 0 = keys, else 2^30 + sum 2^(id - 3), ids 3..26
PTLB_T_DN = 2614      -- Di Nhan set: 0 = off, else 2^30 + sum 2^(id - 43), ids 43..51
PTLB_T_GDS = 2615     -- 1 = Lenh Bai Dao Si given (auto gift)
PTLB_T_GDN = 2616     -- 1 = Lenh Bai Di Nhan given (auto gift)
PTLB_ITEM_DS = 61480
PTLB_ITEM_DN = 61481
PTLB_FLAG = 1073741824

function PTLB_No()
end

function PTLB_Say(title, o)
	local n = getn(o)
	local t = { title, n }
	local k = 1
	while k <= n do t[k + 2] = o[k] k = k + 1 end
	call(Say, t)
end

function PTLB_Pow(k)
	local v = 1
	local i = 0
	while i < k do v = v * 2 i = i + 1 end
	return v
end

-- 1 when bit k of v is set (Lua 4: no bit operators)
function PTLB_Bit(v, k)
	local q = floor(v / PTLB_Pow(k))
	if q - floor(q / 2) * 2 == 1 then return 1 end
	return nil
end

function PTLB_Learnt(id)
	local l = HaveMagic(id)
	if l and l > 0 then return 1 end
	return nil
end

function PTLB_AddSk(t, id, el, kind, nm)
	local s = {}
	s.id = id
	s.el = el
	s.kind = kind
	s.nm = nm
	t.n = t.n + 1
	t[t.n] = s
end

